import json, glob, os, re
B = '/private/tmp/claude-501/-Users-kevingalligan-devel-framejob/9cfd7405-83ec-4caa-905f-7b97a20f2cc9/scratchpad/inventory'
R = '/Users/kevingalligan/devel/framejob/.claude/worktrees/help-docs/'
d = json.load(open(B + '/features/effects.json'))
claimed = {r for x in d['features'] for r in x['raw_ids']}
mine_rej = {x['raw_id']: x['reason'] for x in d['rejected']}
for x in d['features']:
    for c in x['code_refs']:
        m = re.match(r'([^:]+)(?::(\d+))?', c)
        p = R + m.group(1)
        if not os.path.exists(p):
            print('NOFILE', x['id'], c)
        elif m.group(2) and int(m.group(2)) > sum(1 for _ in open(p, errors='ignore')):
            print('PASTEND', x['id'], c)
    for s in [x['summary']]:
        if '—' in s or re.search(r'\b(just|simply|easily)\b', s, re.I):
            print('WORD', x['id'], s)
for f in glob.glob(B + '/features/*.json'):
    if f.endswith('effects.json'):
        continue
    o = json.load(open(f))
    oc = {r for x in o['features'] for r in x['raw_ids']}
    for x in o['rejected']:
        if 'effects' in x['reason'] and x['raw_id'] not in claimed:
            print('OTHER SAYS MINE', os.path.basename(f), x['raw_id'], x['reason'], '| mine:', mine_rej.get(x['raw_id']))
    both = {i for i in mine_rej if i in {y['raw_id'] for y in o['rejected']} and i not in oc}
    sec = o['section']
    for i in both:
        if mine_rej[i] == 'belongs to ' + sec:
            print('HOLE', sec, i)
print('done')

